:root {
  --bg-slip: #1a1a2e;
  --bg-header: #16213e;
  --bg-record-item: #0f3460;
  --bg-badge: #e94560;
  --bg-total: #e94560;
  --color-store-name: #ffffff;
  --color-store-sub: #a0aec0;
  --color-badge-text: #ffffff;
  --color-divider-bg: #2d3748;
  --color-divider-label: #e2c97e;
  --color-record-icon: #e2c97e;
  --color-record-title: #ffffff;
  --color-record-artist: #a0aec0;
  --color-record-price: #e2c97e;
  --color-customer-label: #718096;
  --color-customer-name: #e2e8f0;
  --color-total-label: #ffffff;
  --color-total-amount: #ffffff;
  --border-slip: #2d3748;
}

.slip-wrapper {
  width: 420px;
  background: var(--bg-slip);
  border-radius: 12px;
  border: 1px solid var(--border-slip);
  overflow: hidden;
  margin: 0 auto;
}

.slip-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
}

.store-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.store-name {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--color-store-name);
}

.store-sub {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 1px;
  color: var(--color-store-sub);
  text-transform: uppercase;
}

.slip-badge {
  background: var(--bg-badge);
  color: var(--color-badge-text);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 2px;
  padding: 5px 12px;
  border-radius: 20px;
}

.slip-divider {
  background: var(--color-divider-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px 0;
}

.divider-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--color-divider-label);
}

.slip-body {
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.record-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.record-item {
  background: var(--bg-record-item);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.record-icon {
  font-size: 22px;
  color: var(--color-record-icon);
  line-height: 1;
}

.record-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.record-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--color-record-title);
}

.record-artist {
  font-size: 11px;
  font-weight: 400;
  color: var(--color-record-artist);
}

.record-price {
  font-size: 14px;
  font-weight: 700;
  color: var(--color-record-price);
}

.slip-footer {
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-top: 1px dashed var(--border-slip);
  padding-top: 12px;
}

.customer-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.customer-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--color-customer-label);
}

.customer-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-customer-name);
}

.total-row {
  background: var(--bg-total);
  border-radius: 8px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 12px;
  margin-top: 4px;
}

.total-label {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--color-total-label);
}

.total-amount {
  font-size: 18px;
  font-weight: 800;
  color: var(--color-total-amount);
}
